import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";

const Navbar = () => {
  const navigate = useNavigate();

  return (
    <motion.nav
      initial={{ y: -40, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.7 }}
      className="fixed top-0 w-full z-50 bg-white/10 backdrop-blur-md border-b border-white/20 shadow-sm flex justify-center py-4"
    >
      {/* Text Logo */}
      <motion.h1
        whileHover={{ scale: 1.1 }}
        onClick={() => navigate("/")}
        className="text-2xl md:text-3xl font-extrabold text-blue-700 cursor-pointer tracking-wide"
      >
        AI Interview<span className="text-indigo-600"> Coach</span>
      </motion.h1>
    </motion.nav>
  );
};

export default Navbar;
